inline constexpr std::string_view kDrawEsVertexSource =
    R"CNA_SHADER(#version 310 es
precision highp float;

layout(std430, binding = 7) readonly buffer CnaParticleBuffer
{
    vec4 cnaParticles[];
};

layout(location = 0) in vec3 aPos;
out vec2 vTexCoord;
out vec4 vColor;
out float vViewDepth;

uniform mat4 uParticleMatrices[2];
uniform vec3 uParticleColours[2];
uniform float uParticleScalars[11];

void main()
{
    int base = gl_InstanceID * 3;
    vec3 position = cnaParticles[base].xyz;
    vec4 state = cnaParticles[base + 2];
    float t = clamp(state.x / max(state.y, 1e-4), 0.0, 1.0);
    float size = mix(uParticleScalars[2], uParticleScalars[3], t);
    if (float(gl_InstanceID) >= uParticleScalars[4])
        size = 0.0;

    vec3 viewPosition = (uParticleMatrices[0] * vec4(position, 1.0)).xyz;
    viewPosition.xy += aPos.xy * size;
    gl_Position = uParticleMatrices[1] * vec4(viewPosition, 1.0);
    vTexCoord = aPos.xy + 0.5;
    vColor = vec4(mix(uParticleColours[0], uParticleColours[1], t),
                  mix(uParticleScalars[0], uParticleScalars[1], t));
    vViewDepth = -viewPosition.z;
}
)CNA_SHADER";

inline constexpr std::string_view kDrawEsFragmentSource =
    R"CNA_SHADER(#version 310 es
precision highp float;

in vec2 vTexCoord;
in vec4 vColor;
in float vViewDepth;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uSceneDepth;
uniform float uParticleScalars[11];

float cnaUnpackDepth(vec4 channels)
{
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

void main()
{
    vec4 colour = texture(texture1, vTexCoord) * vColor;
    if (uParticleScalars[5] > 0.5 && uParticleScalars[6] > 0.0)
    {
        vec2 viewportSize = max(vec2(uParticleScalars[8], uParticleScalars[9]), vec2(1.0));
        vec2 uv = gl_FragCoord.xy / viewportSize;
        vec4 depthTexel = texture(uSceneDepth, uv);
        float linearDepth = mix(depthTexel.r, cnaUnpackDepth(depthTexel),
                                clamp(uParticleScalars[10], 0.0, 1.0));
        float behind = linearDepth * uParticleScalars[7];
        colour.a *= clamp((behind - vViewDepth) / uParticleScalars[6], 0.0, 1.0);
    }
    FragColor = colour;
}
)CNA_SHADER";

